*{box-sizing:border-box} body{font-family:Arial,sans-serif;color:#17324d;margin:0}
.mfc{max-width:980px;margin:auto;padding:24px 18px 48px}
.brand{text-align:center;font:700 italic 34px Georgia,serif;color:#173f63}.brand b{color:#d6a400}
.mfc h1{text-align:center;color:#173f63;margin:7px 0;font-size:28px}.sub{text-align:center;font-weight:700;margin-bottom:16px}
.actions{text-align:center;margin:16px 0 26px}.pdfbtn{display:inline-block;background:#173f63;color:#fff!important;text-decoration:none;padding:11px 18px;border-radius:8px;font-weight:700}.pdfbtn:hover{background:#2f75a8}
.q{border:1px solid #d8e2ea;border-radius:12px;padding:18px;margin:18px 0}.q h2{font-size:19px;margin:0 0 10px}.q p{font-size:17px;line-height:1.55}
.art{background:#f7fafc;border:1px solid #dfe8ef;border-radius:10px;padding:14px;margin:12px 0}.tbl{width:100%;border-collapse:collapse}.tbl th,.tbl td{border:1px solid #b9cad7;padding:9px;text-align:center}.tbl th{background:#173f63;color:#fff}
.opts{margin:8px 0 0 22px;line-height:1.8}.lines{height:48px;border-bottom:1px dashed #b9c7d2}
.gab{margin-top:32px}.gab details{border:1px solid #c8dce9;border-radius:10px;overflow:hidden}.gab summary{background:#173f63;color:#fff;padding:13px 18px;font-size:18px;font-weight:700;cursor:pointer;display:flex;justify-content:space-between}.arrow{width:10px;height:10px;border-right:3px solid #fff;border-bottom:3px solid #fff;transform:rotate(45deg)}.gab details[open] .arrow{transform:rotate(225deg)}.gab .inside{padding:14px 18px;background:#f7fafc}
@media print{.gab,.actions{display:none}} @media(max-width:600px){.mfc{padding:18px 12px}.q p{font-size:16px}}
